/**
 * A value shown as text, edited in place (`design/components/inline-edit.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline-edit.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  cell,
  derived,
  elementRef,
  mountEffect,
  presence,
  uniqueId,
  useMember,
  watchEffect,
  type Emitted,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/inline-edit.module.css'
import { Button, type ButtonProps } from './Button'
import { Input, type InputProps } from './Input'

export interface InlineEditMessages {
  edit: (label: string) => string
  save: string
  cancel: string
}

/** A value shown as text, edited in place: the inputs it takes, by the React member's prop names. */
export interface InlineEditProps {
  /**
   * The id of a description of the field and the edit control, as SettingsRow's.
   */
  'aria-describedby'?: string
  /**
   * The id of a label elsewhere that names the field, as SettingsRow's row label does.
   */
  'aria-labelledby'?: string
  /**
   * Uncontrolled: whether the field is open when the member mounts. It takes no focus then.
   */
  defaultEditing?: boolean
  /**
   * The edit control is disabled. The value stays as it is.
   */
  disabled?: boolean
  /**
   * Controlled: whether the field is open. The app closes it once a save succeeds.
   */
  editing?: boolean
  /**
   * The app's message for a failed save, drawn under the field while it is open.
   */
  error?: string
  /**
   * Names the field ("Project name") and, through `messages.edit`, the edit control.
   */
  label: string
  maxLength?: number
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: InlineEditMessages
  /**
   * A save is in flight: the field is read-only, save is busy and cancel is disabled.
   */
  pending?: boolean
  /**
   * Drawn, muted, in place of an empty value, and the empty field's placeholder.
   */
  placeholder?: string
  /**
   * A blank text cannot be saved: the save control is disabled and Enter does nothing.
   */
  required?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The saved value, drawn as text. The app owns it, so after a save it passes the new value.
   */
  value: string
  /**
   * Another element beside the member draws the value, as a page's `<h1>` does: the member draws
   * its edit control and its field, and the value describes the edit control without being
   * drawn. A page's `titleEdit` sets it.
   */
  valueHidden?: boolean
}

/** A value shown as text, edited in place. */
@Component({
  selector: 'pm-inline-edit',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Button, Icon, Input],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-disabled]="e3()"
[attr.data-editing]="e4()"
data-member="inline-edit"
(focusin)="h1()"
(focusout)="h2($event)"
[pmRef]="root"
>@if (e5()) {<!-- panel -->
<div
[attr.class]="e6()"
data-inline-edit-part="panel"
(keydown)="h3($event)"
><!-- row -->
<div
[attr.class]="e7()"
><!-- field -->
<div
[attr.class]="e8()"
><pm-input
[size]="e9()"
[value]="e10()"
[placeholder]="e11()"
[maxLength]="e12()"
[readOnly]="e13()"
[disabled]="e14()"
[invalid]="e15()"
[aria-label]="e16()"
[aria-labelledby]="e17()"
[aria-describedby]="e18()"
[aria-required]="e19()"
(change)="h4($event)"
></pm-input></div>
<pm-button
variant="soft"
tone="accent"
[size]="e20()"
[iconOnly]="e21()"
icon="confirm"
[label]="e22()"
[loading]="e23()"
[disabled]="e24()"
(click)="h5()"
></pm-button>
<pm-button
variant="ghost"
tone="neutral"
[size]="e20()"
[iconOnly]="e21()"
icon="close"
[label]="e25()"
[disabled]="e26()"
(click)="h6()"
></pm-button></div>
<!-- status -->
<div
aria-live="polite"
>@if (e27()) {<!-- error -->
<p
[attr.class]="e28()"
[attr.id]="e29()"
><!-- glyph -->
<span
[attr.class]="e30()"
><pm-icon
name="error"
size="sm"
></pm-icon></span>{{ e31() }}</p>}</div></div>} @else {<!-- value -->
<span
[attr.class]="e32()"
[attr.id]="e33()"
[attr.hidden]="e34()"
[attr.data-placeholder]="e35()"
>{{ e36() }}</span>
<pm-button
variant="ghost"
tone="neutral"
[size]="e37()"
[iconOnly]="e38()"
icon="edit"
[label]="e39()"
[disabled]="e40()"
[aria-describedby]="e41()"
(click)="h7()"
></pm-button>}</div>`,
})
export class InlineEdit {
  /**
   * The id of a description of the field and the edit control, as SettingsRow's.
   */
  readonly ariaDescribedby = input<InlineEditProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * The id of a label elsewhere that names the field, as SettingsRow's row label does.
   */
  readonly ariaLabelledby = input<InlineEditProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  /**
   * Uncontrolled: whether the field is open when the member mounts. It takes no focus then.
   */
  readonly defaultEditing = input<
    Exclude<InlineEditProps['defaultEditing'], undefined>,
    InlineEditProps['defaultEditing']
  >(false, {
    transform: (value: InlineEditProps['defaultEditing']) => (value === undefined ? false : value),
  })
  /**
   * The edit control is disabled. The value stays as it is.
   */
  readonly disabled = input<
    Exclude<InlineEditProps['disabled'], undefined>,
    InlineEditProps['disabled']
  >(false, {
    transform: (value: InlineEditProps['disabled']) => (value === undefined ? false : value),
  })
  /**
   * Controlled: whether the field is open. The app closes it once a save succeeds.
   */
  readonly editing = input<InlineEditProps['editing']>(undefined)
  /**
   * The app's message for a failed save, drawn under the field while it is open.
   */
  readonly error = input<InlineEditProps['error']>(undefined)
  /**
   * Names the field ("Project name") and, through `messages.edit`, the edit control.
   */
  readonly label = input.required<InlineEditProps['label']>()
  readonly maxLength = input<InlineEditProps['maxLength']>(undefined)
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  readonly messages = input<
    Exclude<InlineEditProps['messages'], undefined>,
    InlineEditProps['messages']
  >((() => ({ edit: (label) => `Edit ${label}`, save: 'Save', cancel: 'Cancel' }))(), {
    transform: (value: InlineEditProps['messages']) =>
      value === undefined
        ? (() => ({ edit: (label) => `Edit ${label}`, save: 'Save', cancel: 'Cancel' }))()
        : value,
  })
  /**
   * A save is in flight: the field is read-only, save is busy and cancel is disabled.
   */
  readonly pending = input<
    Exclude<InlineEditProps['pending'], undefined>,
    InlineEditProps['pending']
  >(false, {
    transform: (value: InlineEditProps['pending']) => (value === undefined ? false : value),
  })
  /**
   * Drawn, muted, in place of an empty value, and the empty field's placeholder.
   */
  readonly placeholder = input<InlineEditProps['placeholder']>(undefined)
  /**
   * A blank text cannot be saved: the save control is disabled and Enter does nothing.
   */
  readonly required = input<
    Exclude<InlineEditProps['required'], undefined>,
    InlineEditProps['required']
  >(false, {
    transform: (value: InlineEditProps['required']) => (value === undefined ? false : value),
  })
  readonly size = input<Exclude<InlineEditProps['size'], undefined>, InlineEditProps['size']>(
    'md',
    { transform: (value: InlineEditProps['size']) => (value === undefined ? 'md' : value) },
  )
  /**
   * The saved value, drawn as text. The app owns it, so after a save it passes the new value.
   */
  readonly value = input.required<InlineEditProps['value']>()
  /**
   * Another element beside the member draws the value, as a page's `<h1>` does: the member draws
   * its edit control and its field, and the value describes the edit control without being
   * drawn. A page's `titleEdit` sets it.
   */
  readonly valueHidden = input<
    Exclude<InlineEditProps['valueHidden'], undefined>,
    InlineEditProps['valueHidden']
  >(false, {
    transform: (value: InlineEditProps['valueHidden']) => (value === undefined ? false : value),
  })
  /**
   * The reader saved a changed text, reported as typed. An uncontrolled field closes at once. A
   * controlled one (`editing`) stays open until the app closes it. Not called for an unchanged
   * text.
   */
  readonly onCommit = output<string>({ alias: 'commit' })
  /**
   * The reader opened the field, cancelled, or saved an unchanged text.
   */
  readonly onEditingChange = output<boolean>({ alias: 'editingChange' })
  protected readonly $ = useMember({
    events: ['commit', 'editingChange'],
    props: {
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-labelledby': () => this.ariaLabelledby(),
      defaultEditing: () => this.defaultEditing(),
      disabled: () => this.disabled(),
      editing: () => this.editing(),
      error: () => this.error(),
      label: () => this.label(),
      maxLength: () => this.maxLength(),
      messages: () => this.messages(),
      pending: () => this.pending(),
      placeholder: () => this.placeholder(),
      required: () => this.required(),
      size: () => this.size(),
      value: () => this.value(),
      valueHidden: () => this.valueHidden(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly mirror = cell(() => this.$p.defaultEditing)
  protected readonly draft = cell(() => this.$p.value)
  protected readonly within = cell(() => false)
  protected readonly root = elementRef<HTMLElement>()
  protected readonly current = derived(() => this.$p.editing ?? this.mirror.value)
  protected readonly valueId = derived(() => `${this.uid}-value`)
  protected readonly errorId = derived(() => `${this.uid}-error`)
  protected readonly refused = derived(() => this.$p.required && this.draft.value.trim() === '')
  protected readonly invalid = derived(
    () => this.current.value && this.$p.error !== undefined && this.$p.error !== '',
  )
  protected readonly fieldDescribedBy = derived(
    () =>
      [this.invalid.value ? this.errorId.value : undefined, this.$p['aria-describedby']]
        .filter((id) => id !== undefined)
        .join(' ') || undefined,
  )
  protected readonly editDescribedBy = derived(() =>
    this.$p['aria-describedby'] === undefined
      ? this.valueId.value
      : `${this.valueId.value} ${this.$p['aria-describedby']}`,
  )
  protected readonly setOpen = derived(() => (next: boolean) => {
    this.mirror.value = next
    this.$.emit(this.onEditingChange, 'onEditingChange', next)
  })
  protected readonly open = derived(() => () => {
    this.draft.value = this.$p.value
    this.setOpen.value(true)
  })
  protected readonly cancel = derived(() => () => {
    if (!this.$p.pending) this.setOpen.value(false)
  })
  protected readonly commit = derived(() => () => {
    if (this.$p.pending || this.refused.value) return
    if (this.draft.value === this.$p.value) {
      this.setOpen.value(false)
      return
    }
    this.$.emit(this.onCommit, 'onCommit', this.draft.value)
    if (this.$p.editing === undefined) this.setOpen.value(false)
  })
  protected readonly onKey = derived(() => (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      this.cancel.value()
      return
    }
    if (event.key === 'Enter' && event.target instanceof HTMLInputElement && !event.isComposing) {
      event.preventDefault()
      this.commit.value()
    }
  })
  protected readonly leave = derived(() => (event: FocusEvent) => {
    const next = event.relatedTarget
    if (next instanceof Node && !(this.root.value?.contains(next) ?? false))
      this.within.value = false
  })
  protected readonly saveText = derived(() => (text: string) => {
    if (!this.current.value) throw new Error('The field is closed: edit opens it.')
    if (this.$p.pending) throw new Error('A save is in flight.')
    if (this.$p.required && text.trim() === '') throw new Error('The field is required.')
    this.draft.value = text
    if (text === this.$p.value) {
      this.setOpen.value(false)
      return
    }
    this.$.emit(this.onCommit, 'onCommit', text)
    if (this.$p.editing === undefined) this.setOpen.value(false)
  })
  private release3: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.current.value,
      () => this.effect1(),
      false,
    )
    watchEffect(
      () => this.$p.pending,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.$p.disabled ? '' : undefined
  }

  protected e4() {
    return this.current.value ? '' : undefined
  }

  protected h1(): void {
    this.within.value = true
  }

  protected h2($event: FocusEvent): void {
    this.leave.value($event)
  }

  protected e5() {
    return this.current.value
  }

  protected e6() {
    if (!this.current.value) return undefined as never
    return styles.panel
  }

  protected h3($event: KeyboardEvent): void {
    if (!this.current.value) return
    this.onKey.value($event)
  }

  protected e7() {
    if (!this.current.value) return undefined as never
    return styles.row
  }

  protected e8() {
    if (!this.current.value) return undefined as never
    return styles.field
  }

  protected e9(): InputProps['size'] {
    if (!this.current.value) return undefined as never
    return this.$p.size
  }

  protected e10(): InputProps['value'] {
    if (!this.current.value) return undefined as never
    return this.draft.value
  }

  protected e11(): InputProps['placeholder'] {
    if (!this.current.value) return undefined as never
    return this.$p.placeholder
  }

  protected e12(): InputProps['maxLength'] {
    if (!this.current.value) return undefined as never
    return this.$p.maxLength
  }

  protected e13(): InputProps['readOnly'] {
    if (!this.current.value) return undefined as never
    return this.$p.pending
  }

  protected e14(): InputProps['disabled'] {
    if (!this.current.value) return undefined as never
    return this.$p.disabled
  }

  protected e15(): InputProps['invalid'] {
    if (!this.current.value) return undefined as never
    return this.invalid.value
  }

  protected e16(): InputProps['aria-label'] {
    if (!this.current.value) return undefined as never
    return this.$p['aria-labelledby'] === undefined ? this.$p.label : undefined
  }

  protected e17(): InputProps['aria-labelledby'] {
    if (!this.current.value) return undefined as never
    return this.$p['aria-labelledby']
  }

  protected e18(): InputProps['aria-describedby'] {
    if (!this.current.value) return undefined as never
    return this.fieldDescribedBy.value
  }

  protected e19(): InputProps['aria-required'] {
    if (!this.current.value) return undefined as never
    return this.$p.required ? true : undefined
  }

  protected h4($event: Emitted<Input['onChange']>): void {
    if (!this.current.value) return
    this.draft.value = $event
  }

  protected e20(): ButtonProps['size'] {
    if (!this.current.value) return undefined as never
    return this.$p.size
  }

  protected e21(): ButtonProps['iconOnly'] {
    if (!this.current.value) return undefined as never
    return true
  }

  protected e22(): ButtonProps['label'] {
    if (!this.current.value) return undefined as never
    return this.$p.messages.save
  }

  protected e23(): ButtonProps['loading'] {
    if (!this.current.value) return undefined as never
    return this.$p.pending
  }

  protected e24(): ButtonProps['disabled'] {
    if (!this.current.value) return undefined as never
    return this.$p.disabled || this.refused.value
  }

  protected h5(): void {
    if (!this.current.value) return
    this.commit.value()
  }

  protected e25(): ButtonProps['label'] {
    if (!this.current.value) return undefined as never
    return this.$p.messages.cancel
  }

  protected e26(): ButtonProps['disabled'] {
    if (!this.current.value) return undefined as never
    return this.$p.disabled || this.$p.pending
  }

  protected h6(): void {
    if (!this.current.value) return
    this.cancel.value()
  }

  protected e27() {
    if (!this.current.value) return undefined as never
    return this.invalid.value
  }

  protected e28() {
    if (!this.current.value) return undefined as never
    if (!this.invalid.value) return undefined as never
    return styles.error
  }

  protected e29() {
    if (!this.current.value) return undefined as never
    if (!this.invalid.value) return undefined as never
    return this.errorId.value
  }

  protected e30() {
    if (!this.current.value) return undefined as never
    if (!this.invalid.value) return undefined as never
    return styles.glyph
  }

  protected e31() {
    if (!this.current.value) return undefined as never
    if (!this.invalid.value) return undefined as never
    return this.$p.error
  }

  protected e32() {
    if (this.current.value) return undefined as never
    return styles.value
  }

  protected e33() {
    if (this.current.value) return undefined as never
    return this.valueId.value
  }

  protected e34() {
    if (this.current.value) return undefined as never
    return presence(this.$p.valueHidden)
  }

  protected e35() {
    if (this.current.value) return undefined as never
    return this.$p.value === '' ? '' : undefined
  }

  protected e36() {
    if (this.current.value) return undefined as never
    return (this.$p.value === '' ? this.$p.placeholder : this.$p.value) ?? ''
  }

  protected e37(): ButtonProps['size'] {
    if (this.current.value) return undefined as never
    return this.$p.size
  }

  protected e38(): ButtonProps['iconOnly'] {
    if (this.current.value) return undefined as never
    return true
  }

  protected e39(): ButtonProps['label'] {
    if (this.current.value) return undefined as never
    return this.$p.messages.edit(this.$p.label)
  }

  protected e40(): ButtonProps['disabled'] {
    if (this.current.value) return undefined as never
    return this.$p.disabled
  }

  protected e41(): ButtonProps['aria-describedby'] {
    if (this.current.value) return undefined as never
    return this.editDescribedBy.value
  }

  protected h7(): void {
    if (this.current.value) return
    this.open.value()
  }

  private effect1(): void {
    void (this.current.value
      ? ((this.draft.value = this.$p.value),
        this.$.afterRender(() => {
          const input = this.root.value?.querySelector('input')
          input?.focus()
          input?.select()
        }))
      : this.within.value &&
        this.$.afterRender(() => this.root.value?.querySelector('button')?.focus()))
  }

  private effect2(): void {
    void (
      !this.$p.pending &&
      this.current.value &&
      this.within.value &&
      this.root.value?.querySelector('input')?.focus()
    )
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'InlineEdit',
      element: () =>
        this.root.value?.querySelector('input') ?? this.root.value?.querySelector('button'),
      state: () => ({
        value: this.$p.value,
        editing: this.current.value,
        pending: this.$p.pending,
        error: this.invalid.value ? (this.$p.error ?? '') : '',
        disabled: this.$p.disabled,
      }),
      actions: {
        edit: () =>
          (() => {
            if (!this.current.value) this.open.value()
          })(),
        save: { argument: 'text', run: (value) => this.saveText.value(value) },
        cancel: () =>
          (() => {
            if (this.$p.pending) throw new Error('A save is in flight.')
            if (this.current.value) this.setOpen.value(false)
          })(),
      },
      withholds: () => this.root.value,
    })
    this.release3 = () => {
      ran()
    }
  }
}
